def close(a, b, tol=1e-9):
    return abs(a - b) <= tol * max(1.0, abs(a), abs(b))

assert close(amount_out(100, 400, 100, fee=0), 200)
assert close(amount_out(500, 1_000_000, 5), 1_000_000 * 5 * 0.997 / (500 + 5 * 0.997))
assert amount_out(500, 1_000_000, 0) == 0
for x, y, dx, fee in [(500, 1_000_000, 37.5, 0.003), (1e6, 1e6, 12_345, 0.0005), (3, 7, 100, 0.01)]:
    dy = amount_out(x, y, dx, fee)
    assert 0 < dy < y
    assert (x + dx) * (y - dy) >= x * y * (1 - 1e-12), "a trade must never shrink x * y"
    assert close(amount_in(x, y, dy, fee), dx), "amount_in must invert amount_out"
assert close(amount_in(100, 400, 200, fee=0), 100)
for bad in (400, 401, -1):
    try:
        amount_in(100, 400, bad)
    except ValueError:
        continue
    raise AssertionError(f"amount_in(100, 400, {bad}) should raise ValueError")
assert amount_in(100, 400, 399, fee=0) > 1000 * amount_in(100, 400, 1, fee=0), "the last units cost ever more"

